98	    return (
99	      <div className={css({ display: "flex", minWidth: "max-content", alignItems: "baseline", gap: "0.25rem" })} style={{ paddingLeft: depth * 14 }}>
100	        <span className={css({ color: "var(--muted-foreground)" })}>{name}:</span>
101	        <JsonPrimitive value={value} />
102	      </div>
103	    );
104	  }
105	
106	  const entries = Object.entries(value as JsonNode[] | { [key: string]: JsonNode });
107	  const summary = isArray ? `Array(${entries.length})` : `Object(${entries.length})`;
108	
109	  return (
110	    <div className={css({ minWidth: "max-content" })}>
111	      <button
112	        type="button"
113	        onClick={() => setOpen((next) => !next)}
