125	          ))}
126	        </div>
127	      )}
128	    </div>
129	  );
130	}
131	
132	function JsonPrimitive({ value }: { value: Exclude<JsonNode, JsonNode[] | { [key: string]: JsonNode }> }) {
133	  if (value === null) return <span className={css({ color: "var(--muted-foreground)" })}>null</span>;
