11		normalizeEmail,
12		rememberDioIdentity,
13	} from "../dio-provider";
14	
15	type DioPromptRequest = {
16		id: string;
17		packId?: string;
18		resolve: (success: boolean) => void;
19	};
20	
21	let activeDioPrompt: DioPromptRequest | null = null;
22	
23	export function getActiveDioPrompt(): DioPromptRequest | null {
24		return activeDioPrompt;
25	}
26	
27	function emitDioPromptChange() {
28		window.dispatchEvent(new CustomEvent("keating:dio-prompt-changed"));
29	}
30	
31	export async function promptDioAccess(options?: { packId?: string }): Promise<boolean> {
32		if (typeof window === "undefined") return false;
33		if (!isDioFeatureEnabled()) return false;
34	
35		// Buying a specific pack must open checkout even when a key already exists
36		// (top-ups add credits to the same key).
37		if (!options?.packId) {
38			const existing = await getAppStorage().providerKeys.get(DIO_PROVIDER_ID);
39			if (existing) return true;
40		}
41	
42		if (activeDioPrompt) {
43			activeDioPrompt.resolve(false);
44		}
45	
46		return new Promise((resolve) => {
47			activeDioPrompt = {
48				id: crypto.randomUUID(),
49				packId: options?.packId,
50				resolve,
51			};
52			emitDioPromptChange();
53		});
54	}
55	
56	export function closeDioPrompt(success: boolean) {
57		if (!activeDioPrompt) return;
58		const request = activeDioPrompt;
59		activeDioPrompt = null;
60		request.resolve(success);
61		emitDioPromptChange();
62	}
63	
64	const helperTextClass = css({ fontSize: "0.875rem", color: "var(--muted-foreground)" });
65	const smallHelperTextClass = css({ fontSize: "0.75rem", color: "var(--muted-foreground)" });
66	const linkButtonClass = css({ fontSize: "0.75rem", color: "var(--primary)", textDecoration: "underline", textUnderlineOffset: "2px" });
67	const mutedLinkButtonClass = css({ fontSize: "0.75rem", color: "var(--muted-foreground)", textDecoration: "underline", textUnderlineOffset: "2px" });
68	const errorTextClass = css({ fontSize: "0.75rem", color: "var(--destructive)" });
