70	export function DioAccessPromptDialog() {
71		const [request, setRequest] = useState(activeDioPrompt);
72		const [email, setEmail] = useState("");
73		const [mode, setMode] = useState<"purchase" | "recover" | "manual">("purchase");
74		const [apiKey, setApiKey] = useState("");
75		const [purchaseReference, setPurchaseReference] = useState("");
76		const [otp, setOtp] = useState("");
77		const [requiresOtp, setRequiresOtp] = useState(false);
78		const [devCode, setDevCode] = useState("");
79		const [loading, setLoading] = useState(false);
80		const [error, setError] = useState("");
81	
82		useEffect(() => {
83			const sync = () => {
84				setRequest(activeDioPrompt);
85				setEmail("");
86				setMode("purchase");
87				setApiKey("");
88				setPurchaseReference("");
89				setOtp("");
90				setRequiresOtp(false);
91				setDevCode("");
92				setError("");
93				setLoading(false);
94			};
