96			return () => window.removeEventListener("keating:dio-prompt-changed", sync);
97		}, []);
98	
99		if (!request) return null;
100	
101		const saveManualKey = async () => {
102			const trimmed = apiKey.trim();
103			if (!trimmed) {
104				setError("Enter an API key first.");
105				return;
106			}
107			setLoading(true);
108			setError("");
109			try {
110				await getAppStorage().providerKeys.set(DIO_PROVIDER_ID, trimmed);
111				closeDioPrompt(true);
