132				setError(err instanceof Error ? err.message : String(err));
133			} finally {
134				setLoading(false);
135			}
136		};
137	
138		const doClaim = async () => {
139			const normalized = normalizeEmail(email);
140			if (!isValidEmail(normalized)) {
141				setError("Enter a valid email address.");
142				return;
143			}
144			setLoading(true);
145			setError("");
146			try {
147				const result = await claimDioAccess(normalized, purchaseReference || undefined);
148				if (result.success && result.apiKey) {
149					await getAppStorage().providerKeys.set(DIO_PROVIDER_ID, result.apiKey);
150					await rememberDioIdentity(normalized);
151					closeDioPrompt(true);
152				} else if (result.pending) {
153					setError("Purchase is still pending. Complete payment and try again.");
154				} else {
155					setError("Could not find a completed purchase for this email.");
156				}
157			} catch (err) {
158				setError(err instanceof Error ? err.message : String(err));
159			} finally {
160				setLoading(false);
161			}
162		};
163	
164		const doRecover = async () => {
165			const normalized = normalizeEmail(email);
166			if (!isValidEmail(normalized)) {
167				setError("Enter a valid email address.");
168				return;
169			}
170			setLoading(true);
171			setError("");
172			try {
173				const result = await recoverDioAccess(normalized, otp || undefined);
174				if (result.success && result.apiKey) {
175					await getAppStorage().providerKeys.set(DIO_PROVIDER_ID, result.apiKey);
176					await rememberDioIdentity(normalized);
177					closeDioPrompt(true);
178				} else if (result.requiresOtp) {
179					setRequiresOtp(true);
180					setDevCode(result.devCode || "");
181					setError(otp ? "Invalid or expired code." : "Enter the verification code sent to your email.");
182				} else {
