194				<div className={css({ width: "100%", maxWidth: "28rem", borderRadius: "0.5rem", border: "1px solid var(--border)", backgroundColor: "var(--background)", boxShadow: "var(--shadow-xl)" })}>
195					<div className={css({ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "0.75rem", borderBottom: "1px solid var(--border)", paddingInline: "1rem", paddingBlock: "0.75rem" })}>
196						<div className={css({ display: "flex", alignItems: "center", gap: "0.5rem" })}>
197							<KeyRound size={16} className={css({ color: "var(--primary)" })} />
198							<h2 className={css({ fontSize: "0.875rem", fontWeight: 600 })}>Dio access</h2>
199						</div>
