/* Import base styles from pi-web-ui (compiled Tailwind + KaTeX + themes).
   MUST come before the local Tailwind import: pi-web-ui's compiled bundle
   contains base utilities (.hidden, .flex, .w-full) without responsive
   variants, and whichever stylesheet is imported later wins within the
   merged `utilities` layer. Importing it first lets local responsive
   variants (e.g. `sm:flex`) override its base utilities as Tailwind
   intends. */
@import "@earendil-works/pi-web-ui/app.css";

/* Retro theme for landing, tutorial, blog */
@import "./styles/retro.css";

/* Panda CSS layers. PostCSS fills these from web/panda.config.ts. */
@layer reset, base, tokens, recipes, utilities;

/* ────────────────────────────────────────────────────────────────
   RETRO THEME OVERRIDES — overrides pi-web-ui default tokens
   with retro paper/terminal values so the entire app feels
   consistent with the landing page aesthetic.
   ──────────────────────────────────────────────────────────────── */

:root {
  /* Core retro brand tokens globally available */
  --paper: #f1ece0;
  --paper-deep: #e9e2d2;
  --ink: #1c211b;
  --ink-soft: #4a5247;
  --green: #1e9b50;
  --green-deep: #14743c;
  --green-wash: #ddebdd;
  --crt: #0c1510;
  --crt-edge: #1b2a1f;
  --phosphor: #4be388;
  --phosphor-dim: #2e9a5c;
  --amber: #e8a33d;
  --red: #d5604b;
  --line: rgba(28, 33, 27, 0.22);
  --line-soft: rgba(28, 33, 27, 0.12);
  --accent-green: #1e9b50;
  --shadow-card:
    0 1px 0 rgba(28, 33, 27, 0.06), 0 10px 28px -18px rgba(28, 33, 27, 0.35);
  --mono-display:
    "Space Mono", ui-monospace, "Cascadia Mono", Menlo, monospace;
  --mono-body:
    "JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, monospace;
  --font-ui:
    system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  /* Paper palette (light mode — default) */
  --background: #f1ece0;
  --foreground: #1c211b;
  --card: #f6f2e8;
  --card-foreground: #1c211b;
  --popover: #f6f2e8;
  --popover-foreground: #1c211b;
  --primary: #1e9b50;
  --primary-foreground: #ffffff;
  --secondary: #e9e2d2;
  --secondary-foreground: #1c211b;
  --muted: #e9e2d2;
  --muted-foreground: #4a5247;
  --accent: #ddebdd;
  --accent-foreground: #14743c;
  --destructive: #b9432e;
  --destructive-foreground: #ffffff;
  --border: #1c211b;
  --input: #1c211b;
  --ring: #1e9b50;
  --chart-1: #1e9b50;
  --chart-2: #14743c;
  --chart-3: #2e9a5c;
  --chart-4: #e8a33d;
  --chart-5: #d5604b;
  --sidebar: #e9e2d2;
  --sidebar-foreground: #1c211b;
  --sidebar-primary: #1e9b50;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #ddebdd;
  --sidebar-accent-foreground: #14743c;
  --sidebar-border: #1c211b;
  --sidebar-ring: #1e9b50;
  --font-sans: "Roboto", "Segoe UI", Arial, sans-serif;
  --font-serif: Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,
    "Liberation Mono", "Courier New", monospace;
  --radius: 0.25rem;
}

.dark {
  /* CRT phosphor palette (dark mode) */
  --paper: #0c1510;
  --paper-deep: #0a110d;
  --ink: #dcefe0;
  --ink-soft: #9dbfa8;
  --line: rgba(75, 227, 136, 0.28);
  --line-soft: rgba(75, 227, 136, 0.14);
  --shadow-card:
    0 1px 0 rgba(0, 0, 0, 0.4), 0 10px 28px -18px rgba(0, 0, 0, 0.8);
  --font-ui:
    system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --background: #0c1510;
  --foreground: #dcefe0;
  --card: #11201a;
  --card-foreground: #dcefe0;
  --popover: #11201a;
  --popover-foreground: #dcefe0;
  --primary: #4be388;
  --primary-foreground: #0c1510;
  --secondary: #1b2a1f;
  --secondary-foreground: #dcefe0;
  --muted: #16231b;
  --muted-foreground: #8fbf9e;
  --accent: rgba(75, 227, 136, 0.12);
  --accent-foreground: #4be388;
  --destructive: #d5604b;
  --destructive-foreground: #f1ece0;
  --border: rgba(75, 227, 136, 0.28);
  --input: rgba(75, 227, 136, 0.32);
  --ring: #4be388;
  --chart-1: #4be388;
  --chart-2: #2e9a5c;
  --chart-3: #1e9b50;
  --chart-4: #e8a33d;
  --chart-5: #d5604b;
  --sidebar: #0a110d;
  --sidebar-foreground: #dcefe0;
  --sidebar-primary: #4be388;
  --sidebar-primary-foreground: #0c1510;
  --sidebar-accent: rgba(75, 227, 136, 0.12);
  --sidebar-accent-foreground: #4be388;
  --sidebar-border: rgba(75, 227, 136, 0.28);
  --sidebar-ring: #4be388;
  --font-sans: "Roboto", "Segoe UI", Arial, sans-serif;
  --font-serif: Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,
    "Liberation Mono", "Courier New", monospace;
  --radius: 0.25rem;
}

/* Custom Keating styles */
html,
body,
#root {
  height: 100%;

export default defineConfig({
  preflight: true,
  jsxFramework: "react",
  jsxStyleProps: "none",
  include: [
    "./src/**/*.{ts,tsx,js,jsx}",
    "./server/**/*.{ts,tsx,js,jsx}",
    "./.storybook/**/*.{ts,tsx,js,jsx}",
    "./index.html"
  ],
  exclude: ["node_modules", "dist", ".output", "public"],
  outdir: "styled-system",
  theme: {
    extend: {
      tokens: {
        colors: {
          paper: { value: "#f1ece0" },
          paperDeep: { value: "#e9e2d2" },
          card: { value: "#f6f2e8" },
          ink: { value: "#1c211b" },
          inkSoft: { value: "#4a5247" },
          accent: { value: "#1e9b50" },
          accentDim: { value: "#14743c" },
          greenWash: { value: "#ddebdd" },
          terminal: { value: "#0c1510" },
          terminalEdge: { value: "#1b2a1f" },
          phosphor: { value: "#4be388" },
          phosphorDim: { value: "#2e9a5c" },
          amber: { value: "#e8a33d" },
          red: { value: "#d5604b" }
        },
        fonts: {
          monoDisplay: { value: fonts.monoDisplay },
          monoBody: { value: fonts.monoBody },
          ui: { value: fonts.ui }
        },
        radii: {
          keating: { value: "0.25rem" }
        },
        shadows: {
          card: {
            value: "0 1px 0 rgba(28, 33, 27, 0.06), 0 10px 28px -18px rgba(28, 33, 27, 0.35)"
          },
          hard: { value: "4px 4px 0 var(--ink)" },
          crt: { value: "6px 6px 0 var(--ink)" }
        }
      },
      recipes
    }
  },
  globalCss: {
    ":root": {
      colorScheme: "light",
      "--paper": "{colors.paper}",
      "--paper-deep": "{colors.paperDeep}",
      "--card": "{colors.card}",
      "--ink": "{colors.ink}",
      "--ink-soft": "{colors.inkSoft}",
      "--accent": "{colors.accent}",
      "--accent-dim": "{colors.accentDim}",
      "--green-wash": "{colors.greenWash}",
      "--terminal": "{colors.terminal}",
      "--terminal-edge": "{colors.terminalEdge}",
      "--phosphor": "{colors.phosphor}",
      "--phosphor-dim": "{colors.phosphorDim}",
      "--amber": "{colors.amber}",
      "--red": "{colors.red}",
      "--line": "rgba(28, 33, 27, 0.22)",
      "--line-soft": "rgba(28, 33, 27, 0.12)",
      "--mono-display": fonts.monoDisplay,
      "--mono-body": fonts.monoBody,
      "--font-ui": fonts.ui,
      "--shadow-card": "{shadows.card}",
      "--radius": "{radii.keating}"
    },
    ".dark": {
      colorScheme: "dark",
      "--paper": "{colors.terminal}",
      "--paper-deep": "#0a110d",
      "--card": "#11201a",
      "--ink": "#dcefe0",
      "--ink-soft": "#9dbfa8",
      "--accent": "{colors.phosphor}",
      "--accent-dim": "{colors.phosphor}",
      "--green-wash": "rgba(75, 227, 136, 0.12)",
      "--line": "rgba(75, 227, 136, 0.28)",
      "--line-soft": "rgba(75, 227, 136, 0.14)",
      "--shadow-card": "0 1px 0 rgba(0, 0, 0, 0.4), 0 10px 28px -18px rgba(0, 0, 0, 0.8)"
    },
    ".keating-artifact": {
      minHeight: "100vh",
      padding: "clamp(1rem, 3vw, 2.5rem)"
    },
    ".keating-artifact-shell": {
      width: "min(92vw, 1280px)",
      margin: "0 auto",
      display: "grid",
      gap: "1rem"
    },
    ".keating-artifact-header": {
      display: "flex",
      justifyContent: "space-between",
      gap: "1rem",
      alignItems: "end",
      border: "1.5px solid var(--ink)",
      background: "var(--card)",
      boxShadow: "4px 4px 0 var(--ink)",
      padding: "clamp(1rem, 2vw, 1.5rem)"
    },
    ".keating-artifact-title": {
      margin: "0.25rem 0 0",
      color: "var(--accent-dim)",
      fontFamily: "var(--mono-display)",
      fontSize: "clamp(1.8rem, 4vw, 3.5rem)",
      lineHeight: "1.05",
      letterSpacing: "-0.025em"
    },
    ".keating-artifact-meta": {
      color: "var(--ink-soft)",
      fontSize: "0.78rem",
      letterSpacing: "0.12em",
      textTransform: "uppercase"
    },
    ".keating-artifact-links": {
      display: "grid",
      gap: "0.35rem",
      justifyItems: "end",
      fontSize: "0.86rem"
    },
    ".keating-crt-panel": {
      position: "relative",
      overflow: "hidden",
      border: "1.5px solid var(--ink)",
      background: "var(--terminal)",
      color: "var(--phosphor)",
      boxShadow: "6px 6px 0 var(--ink)"
    },
    ".keating-crt-panel::after": {
      content: '""',
      position: "absolute",
      inset: 0,
      pointerEvents: "none",
      background: "repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.16) 0 1px, transparent 1px 3px)",
      mixBlendMode: "multiply"
    },
    "@media (max-width: 720px)": {
      ".keating-artifact-header": {
        alignItems: "start",
        flexDirection: "column"
      },
      ".keating-artifact-links": {
        justifyItems: "start"
      }
    }
  }
});

