2	   MUST come before the local Tailwind import: pi-web-ui's compiled bundle
3	   contains base utilities (.hidden, .flex, .w-full) without responsive
4	   variants, and whichever stylesheet is imported later wins within the
5	   merged `utilities` layer. Importing it first lets local responsive
6	   variants (e.g. `sm:flex`) override its base utilities as Tailwind
7	   intends. */
8	@import "@earendil-works/pi-web-ui/app.css";
9	
10	/* Retro theme for landing, tutorial, blog */
11	@import "./styles/retro.css";
