			options: ["pytest", "pkg-config", "requests", "setuptools-scm", "openssl"],
			correctAnswer: "pytest, pkg-config, setuptools-scm",
			correctAnswers: ["pytest", "pkg-config", "setuptools-scm"],
			explanation:
