const fonts = {
  monoDisplay: '"Space Mono", ui-monospace, "Cascadia Mono", Menlo, monospace',
  monoBody: '"JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, monospace',
  ui: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
};

/**
 * Common UI recipes shared across the migrated Tailwind → Panda CSS code.
 * These collapse the most frequently-inlined patterns (icon button, popover,
 * destructive banner, chip/badge, glass pill, input, content card) into a
 * single typed selector so component code reads as `button({ variant })
 * instead of repeating 6-10 CSS properties per site.
 */
const recipes = {
  /** Square icon-only button (28/32/40 sizes). `tone=primary` fills with the
   * primary color; `tone=ghost` (default) just shows the hover accent. */
  iconButton: {
    className: "keating-icon-btn",
    base: {
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      borderRadius: "0.375rem",
      flexShrink: 0,
      color: "var(--muted-foreground)",
      transition: "background-color 0.12s ease, color 0.12s ease",
      "&:not(:disabled)": { cursor: "pointer" }
    },
    variants: {
      size: {
        sm: { height: "1.75rem", width: "1.75rem" },
        md: { height: "2.5rem", width: "2.5rem" }
      },
      tone: {
        ghost: {
          _hover: { background: "var(--accent)", color: "var(--accent-foreground)" },
          _disabled: { opacity: 0.5 }
        },
        primary: {
          background: "var(--primary)",
          color: "var(--primary-foreground)",
          _hover: { background: "color-mix(in srgb, var(--primary) 90%, black)" },
          _disabled: { opacity: 0.5 }
        }
      }
    },
    defaultVariants: { size: "md", tone: "ghost" }
  },

  /** Dropdown / popover menu surface — rounded card with border + shadow. */
  popover: {
    className: "keating-popover",
    base: {
      position: "absolute",
      zIndex: 20,
      overflow: "hidden",
      borderRadius: "0.5rem",
      border: "1px solid var(--border)",
      background: "var(--background)",
      paddingBlock: "0.25rem",
      boxShadow: "var(--shadow-lg)"
    }
  },

  /** Small status label / chip — uses `intent` to choose the color story. */
  chip: {
    className: "keating-chip",
    base: {
      display: "inline-flex",
      alignItems: "center",
      gap: "0.125rem",
      flexShrink: 0,
      borderRadius: "0.25rem",
      fontSize: "0.625rem",
      fontWeight: 500
    },
    variants: {
      size: {
        sm: { padding: "0.125rem 0.375rem" },
        md: { padding: "0.25rem 0.5rem", fontSize: "0.6875rem" }
      },
      intent: {
        muted: { background: "var(--muted)", color: "var(--muted-foreground)" },
        primary: { background: "var(--primary)", color: "var(--primary-foreground)" },
        plain: {}
      }
    },
    defaultVariants: { size: "sm", intent: "muted" }
  },

  /** Highlighted row for "Delete session?" / "Delete account?" warnings. */
  dangerBanner: {
    className: "keating-danger-banner",
    base: {
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      gap: "0.75rem",
      borderRadius: "0.375rem",
      border: "1px solid color-mix(in srgb, var(--destructive) 30%, transparent)",
      background: "color-mix(in srgb, var(--destructive) 5%, transparent)",
      padding: "0.75rem",
      fontSize: "0.875rem"
    }
  },

  /** Text input + select field with focus ring. */
  input: {
    className: "keating-input",
    base: {
      minWidth: 0,
      borderRadius: "0.375rem",
      border: "1px solid var(--border)",
      background: "var(--background)",
      outline: "none",
      _placeholder: { color: "var(--muted-foreground)" },
      _focus: { borderColor: "var(--ring)" }
    },
    variants: {
      size: {
        sm: { padding: "0.375rem 0.5rem", fontSize: "0.75rem" },
        md: { padding: "0.5rem 0.75rem", fontSize: "0.875rem" }
      }
    },
    defaultVariants: { size: "md" }
  },

  /** Frosted pill used for overlays (count badges, fork labels). */
  glassPill: {
    className: "keating-glass-pill",
    base: {
      display: "inline-flex",
      alignItems: "center",
      gap: "0.25rem",
      borderRadius: "9999px",
      background: "color-mix(in srgb, var(--background) 80%, transparent)",
      color: "var(--foreground)",
      padding: "0.125rem 0.5rem",
      fontSize: "0.625rem",
      fontWeight: 500,
      backdropFilter: "blur(8px)",
      WebkitBackdropFilter: "blur(8px)"
    }
  },

  /** Bordered card surface used by panels, sections, and popovers. */
  panel: {
    className: "keating-panel",
    base: {
      minWidth: 0,
      overflow: "hidden",
      borderRadius: "0.5rem",
      border: "1px solid var(--border)",
      background: "var(--background)"
    }
  },

  /** Centered horizontal stack with even spacing. */
  hstackCenter: {
    className: "keating-hstack-center",
    base: {
      display: "flex",
      alignItems: "center",
      gap: "0.5rem"
    }
  },

  /**
   * Settings panel primitives. Replaces a triplicated set of `section*Class`
   * declarations across KeatingUiSettingsTab, SpeechSettingsTab, and the
   * `settings/*Section.tsx` panels. Use one of these in every settings card.
   */
  settingsSection: {
    className: "keating-settings-section",
    base: {
      display: "flex",
      flexDirection: "column",
      gap: "1rem"
    }
  },

  /** Stacked card surface used inside settings panels for a single setting. */
  settingsCard: {
    className: "keating-settings-card",
    base: {
      display: "flex",
      flexDirection: "column",
      gap: "0.75rem",
      borderRadius: "0.5rem",
      border: "1px solid var(--border)",
      padding: "1rem",
      sm: { flexDirection: "row", alignItems: "flex-start", justifyContent: "space-between", gap: "1rem" }
    },
    variants: {
      tone: {
        default: {},
        subtle: { gap: "1rem", sm: { alignItems: "center" } }
      }
    },
    defaultVariants: { tone: "default" }
  },

  /**
   * Field-level text input / select / number-input. Replaces the per-file
   * `responsiveSelectClass`/`wideResponsiveInputClass` duplicates.
   * Use `fieldInput({ size: "auto" })` for select-style inline controls.
   */
  fieldInput: {
    className: "keating-field-input",
    base: {
      width: "100%",
      borderRadius: "0.375rem",
      border: "1px solid var(--border)",
      backgroundColor: "var(--background)",
      paddingInline: "0.75rem",
      paddingBlock: "0.5rem",
      fontSize: "0.875rem",
      color: "var(--foreground)",
      outline: "none",
      _placeholder: { color: "var(--muted-foreground)" },
      _focus: { borderColor: "var(--ring)" },
      sm: { width: "auto" }
    },
    variants: {
      size: {
        auto: { sm: { minWidth: "11rem" } },
        wide: { sm: { minWidth: "16rem" } },
        tight: { height: "2.25rem", sm: { minWidth: "4rem", paddingInline: "0.5rem" } }
      }
    },
    defaultVariants: { size: "auto" }
  },

  /**
   * Radio-row card used for selecting among 2–6 options. Provides a
   * visible selected state (border highlight + tinted background) and a
   * hover state to indicate clickability.
   */
  radioCard: {
    className: "keating-radio-card",
    base: {
      display: "flex",
      cursor: "pointer",
      alignItems: "center",
      gap: "0.75rem",
      borderRadius: "0.375rem",
      border: "1px solid var(--border)",
      paddingInline: "0.75rem",
      paddingBlock: "0.5rem",
      transitionProperty: "color, background-color, border-color",
      transitionDuration: "150ms",
      _hover: { backgroundColor: "color-mix(in srgb, var(--accent) 50%, transparent)" }
    },
    variants: {
      active: {
        true: {
          backgroundColor: "color-mix(in srgb, var(--primary) 10%, transparent)",
          borderColor: "color-mix(in srgb, var(--primary) 40%, transparent)"
        },
        false: {}
      }
    },
    defaultVariants: { active: false }
  },

  /**
   * Tab button used by the settings dialog sidebar and mobile tab bar.
   * Replaces two near-identical `idle`/`active` template literals.
   */
  settingsTabButton: {
    className: "keating-settings-tab-button",
    base: {
      borderRadius: "0.375rem",
      fontSize: "0.875rem",
      transitionProperty: "color, background-color, border-color",
      transitionDuration: "150ms"
    },
    variants: {
      active: {
        true: {
          backgroundColor: "color-mix(in srgb, var(--primary) 10%, transparent)",
          color: "var(--primary)",
          fontWeight: 500
        },
        false: {
          color: "var(--muted-foreground)",
          _hover: { backgroundColor: "var(--accent)", color: "var(--accent-foreground)" }
        }
      },
      shape: {
        sidebar: {
          display: "inline-flex",
          alignItems: "center",
          gap: "0.5rem",
          textAlign: "left",
          paddingInline: "0.75rem",
          paddingBlock: "0.5rem"
        },
        bar: {
          whiteSpace: "nowrap",
          paddingInline: "0.75rem",
          paddingBlock: "0.375rem",
          minHeight: "2.25rem",
          border: "1px solid var(--border)"
        }
      }
    },
    defaultVariants: { active: false, shape: "sidebar" }
  },

  /** Primary action button used in settings panels. */
  primaryButton: {
    className: "keating-primary-button",
    base: {
      display: "inline-flex",
      height: "2.25rem",
      alignItems: "center",
      justifyContent: "center",
      gap: "0.5rem",
      borderRadius: "0.375rem",
      backgroundColor: "var(--primary)",
      paddingInline: "1rem",
      fontSize: "0.875rem",
      fontWeight: 500,
      color: "var(--primary-foreground)",
      transitionProperty: "background-color",
      transitionDuration: "150ms",
      _hover: { backgroundColor: "color-mix(in srgb, var(--primary) 90%, black)" },
      _disabled: { opacity: 0.5, cursor: "not-allowed" }
    }
  },

  /** Outline / secondary button used for cancel / less-emphatic actions. */
  outlineButton: {
    className: "keating-outline-button",
    base: {
      display: "inline-flex",
      height: "2.25rem",
      alignItems: "center",
      justifyContent: "center",
      gap: "0.5rem",
      borderRadius: "0.375rem",
      border: "1px solid var(--border)",
      paddingInline: "1rem",
      fontSize: "0.875rem",
      fontWeight: 500,
      transitionProperty: "color, background-color, border-color",
      transitionDuration: "150ms",
      _hover: { backgroundColor: "var(--accent)", color: "var(--accent-foreground)" },
      _disabled: { opacity: 0.5 }
    }
  },

  /** Multi-line text input used in panels (persona prompt, system prompt, …). */
  textarea: {
    className: "keating-textarea",
    base: {
      minHeight: "17.5rem",
      width: "100%",
      resize: "vertical",
      borderRadius: "0.5rem",
      border: "1px solid var(--border)",
      backgroundColor: "var(--background)",
      padding: "0.75rem",
      fontFamily: "var(--mono-display)",
      fontSize: "0.75rem",
      lineHeight: "1.25rem",
      color: "var(--foreground)",
      outline: "none",
      _focus: { borderColor: "var(--ring)" }
    }
  }
} as const;

