1	/* Import base styles from pi-web-ui (compiled Tailwind + KaTeX + themes).
2	   MUST come before the local Tailwind import: pi-web-ui's compiled bundle
3	   contains base utilities (.hidden, .flex, .w-full) without responsive
4	   variants, and whichever stylesheet is imported later wins within the
5	   merged `utilities` layer. Importing it first lets local responsive
6	   variants (e.g. `sm:flex`) override its base utilities as Tailwind
7	   intends. */
8	@import "@earendil-works/pi-web-ui/app.css";
9	
10	/* Retro theme for landing, tutorial, blog */
11	@import "./styles/retro.css";
12	
13	/* Panda CSS layers. PostCSS fills these from web/panda.config.ts. */
14	@layer reset, base, tokens, recipes, utilities;
15	
16	/* ────────────────────────────────────────────────────────────────
17	   RETRO THEME OVERRIDES — overrides pi-web-ui default tokens
18	   with retro paper/terminal values so the entire app feels
19	   consistent with the landing page aesthetic.
20	   ──────────────────────────────────────────────────────────────── */
21	
22	:root {
23	  /* Core retro brand tokens globally available */
24	  --paper: #f1ece0;
25	  --paper-deep: #e9e2d2;
26	  --ink: #1c211b;
27	  --ink-soft: #4a5247;
28	  --green: #1e9b50;
29	  --green-deep: #14743c;
30	  --green-wash: #ddebdd;
31	  --crt: #0c1510;
32	  --crt-edge: #1b2a1f;
33	  --phosphor: #4be388;
34	  --phosphor-dim: #2e9a5c;
35	  --amber: #e8a33d;
36	  --red: #d5604b;
37	  --line: rgba(28, 33, 27, 0.22);
38	  --line-soft: rgba(28, 33, 27, 0.12);
39	  --accent-green: #1e9b50;
40	  /* Aliases for names only previously declared in panda.config.ts globalCss
41	     (now consolidated here as the single source for all CSS custom properties). */
