1	import { useEffect, useState } from "react";
2	import { getAppStorage } from "@earendil-works/pi-web-ui";
3	import { KeyRound, X } from "lucide-react";
4	import { css, cx } from "../../styled-system/css";
5	import { iconButton, primaryButton } from "../../styled-system/recipes";
6	import {
7		DIO_PROVIDER_ID,
8		claimDioAccess,
9		isDioFeatureEnabled,
10		recoverDioAccess,
11		startDioCheckout,
12		normalizeEmail,
13		rememberDioIdentity,
14	} from "../dio-provider";
15	
16	type DioPromptRequest = {
17		id: string;
18		packId?: string;
19		resolve: (success: boolean) => void;
20	};
21	
22	let activeDioPrompt: DioPromptRequest | null = null;
23	
24	export function getActiveDioPrompt(): DioPromptRequest | null {
25		return activeDioPrompt;
26	}
27	
28	function emitDioPromptChange() {
29		window.dispatchEvent(new CustomEvent("keating:dio-prompt-changed"));
30	}
31	
32	export async function promptDioAccess(options?: { packId?: string }): Promise<boolean> {
33		if (typeof window === "undefined") return false;
34		if (!isDioFeatureEnabled()) return false;
35	
36		// Buying a specific pack must open checkout even when a key already exists
37		// (top-ups add credits to the same key).
38		if (!options?.packId) {
39			const existing = await getAppStorage().providerKeys.get(DIO_PROVIDER_ID);
40			if (existing) return true;
41		}
42	
43		if (activeDioPrompt) {
44			activeDioPrompt.resolve(false);
45		}
46	
47		return new Promise((resolve) => {
48			activeDioPrompt = {
49				id: crypto.randomUUID(),
50				packId: options?.packId,
51				resolve,
52			};
53			emitDioPromptChange();
54		});
55	}
56	
57	export function closeDioPrompt(success: boolean) {
58		if (!activeDioPrompt) return;
59		const request = activeDioPrompt;
60		activeDioPrompt = null;
61		request.resolve(success);
62		emitDioPromptChange();
63	}
64	
