1	import { useCallback, useEffect, useState } from "react";
2	import { Moon, Sun } from "lucide-react";
3	import { css } from "../../styled-system/css";
4	import { iconButton } from "../../styled-system/recipes";
5	
6	const menuButtonClass = css({
7	  display: "flex",
8	  alignItems: "center",
9	  gap: "0.5rem",
10	  borderRadius: "0.375rem",
11	  paddingInline: "0.75rem",
12	  paddingBlock: "0.5rem",
13	  textAlign: "left",
14	  fontSize: "0.875rem",
15	  transitionProperty: "color, background-color",
16	  transitionDuration: "{durations.fast}",
17	  transitionTimingFunction: "{easings.standard}",
18	  _hover: { background: "var(--accent)", color: "var(--accent-foreground)" },
19	});
20	
21	const iconButtonClass = iconButton({ size: "lg", tone: "ghost" });
22	
23	function getInitialTheme(): boolean {
24	  if (typeof document === "undefined") return false;
25	  const root = document.documentElement;
26	  if (root.classList.contains("dark") || root.classList.contains("light")) {
27	    return root.classList.contains("dark");
28	  }
29	  const stored = localStorage.getItem("theme");
30	  if (stored === "dark") return true;
31	  if (stored === "light") return false;
32	  return window.matchMedia("(prefers-color-scheme: dark)").matches;
33	}
34	
35	interface ThemeToggleProps {
36	  className?: string;
37	  /** "icon" (default) renders the square header button; "menu" renders a full-width labeled row for the overflow menu. */
38	  variant?: "icon" | "menu";
39	  /** Called after the theme is toggled (e.g. to close the overflow menu). */
40	  onToggled?: () => void;
41	}
42	
43	export function ThemeToggle({ className = "", variant = "icon", onToggled }: ThemeToggleProps = {}) {
44	  const [isDark, setIsDark] = useState(() => getInitialTheme());
45	
46	  useEffect(() => {
47	    const observer = new MutationObserver(() => {
48	      setIsDark(document.documentElement.classList.contains("dark"));
49	    });
50	    observer.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
51	    return () => observer.disconnect();
52	  }, []);
53	
54	  const toggle = useCallback(() => {
55	    const root = document.documentElement;
56	    const next = !root.classList.contains("dark");
57	    if (next) {
58	      root.classList.add("dark");
59	      localStorage.setItem("theme", "dark");
60	    } else {
61	      root.classList.remove("dark");
62	      localStorage.setItem("theme", "light");
63	    }
64	    setIsDark(next);
65	    onToggled?.();
66	  }, [onToggled]);
67	
68	  const label = isDark ? "Switch to light mode" : "Switch to dark mode";
69	
70	  if (variant === "menu") {
71	    return (
72	      <button
73	        type="button"
74	        onClick={toggle}
75	        className={`${menuButtonClass} ${className}`.trim()}
76	        aria-label={label}
77	      >
78	        {isDark ? <Sun size={14} /> : <Moon size={14} />}
79	        {isDark ? "Light mode" : "Dark mode"}
80	      </button>
81	    );
82	  }
83	
84	  return (
85	    <button
86	      type="button"
87	      onClick={toggle}
88	      className={`chat-action-button ${iconButtonClass} ${className}`.trim()}
89	      title={label}
90	      aria-label={label}
91	    >
92	      {isDark ? <Sun size={16} /> : <Moon size={16} />}
93	    </button>
94	  );
95	}
