import { css } from "../../styled-system/css";

const COLOR_GROUPS: { title: string; names: string[] }[] = [
	{
		title: "Surfaces",
		names: ["background", "foreground", "card", "cardForeground", "popover", "popoverForeground", "paper", "paperDeep"],
	},
	{
		title: "Brand",
		names: ["primary", "primaryForeground", "secondary", "secondaryForeground", "accent", "accentDim"],
	},
	{
		title: "Muted / surface accents",
		names: ["muted", "mutedForeground", "accentSurface", "accentSurfaceForeground"],
	},
	{
		title: "Status",
		names: ["destructive", "destructiveForeground"],
	},
	{
		title: "Structure",
		names: ["border", "input", "ring", "line", "lineSoft"],
	},
	{
		title: "Charts",
		names: ["chart1", "chart2", "chart3", "chart4", "chart5"],
	},
	{
		title: "Sidebar",
		names: [
			"sidebar",
			"sidebarForeground",
			"sidebarPrimary",
			"sidebarPrimaryForeground",
			"sidebarAccent",
			"sidebarAccentForeground",
			"sidebarBorder",
			"sidebarRing",
		],
	},
];

const CAMEL_TO_KEBAB = (name: string) => name.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

const pageClass = css({
	padding: "2rem",
	fontFamily: "{fonts.ui}",
	background: "var(--background)",
	color: "var(--foreground)",
	minHeight: "100vh",
});

const sectionTitleClass = css({
	fontSize: "1.25rem",
	fontWeight: 600,
	marginTop: "2rem",
	marginBottom: "0.75rem",
});

const swatchGridClass = css({
	display: "grid",
	gridTemplateColumns: "repeat(auto-fill, minmax(11rem, 1fr))",
	gap: "0.75rem",
});

const swatchClass = css({
	borderRadius: "0.5rem",
	border: "1px solid var(--border)",
	overflow: "hidden",
	fontSize: "0.75rem",
});

const swatchFillClass = css({
	height: "3.5rem",
});

const swatchLabelClass = css({
	padding: "0.5rem",
	background: "var(--card)",
	color: "var(--cardForeground)",
});

function ColorSwatch({ name }: { name: string }) {
	return (
		<div className={swatchClass}>
			<div className={swatchFillClass} style={{ background: `var(--${CAMEL_TO_KEBAB(name)})` }} />
			<div className={swatchLabelClass}>
				<div style={{ fontWeight: 600 }}>{name}</div>
				<div style={{ opacity: 0.6 }}>--{CAMEL_TO_KEBAB(name)}</div>
			</div>
		</div>
	);
}

const typeRowClass = css({
	display: "flex",
	alignItems: "baseline",
	gap: "1rem",
	paddingBlock: "0.5rem",
	borderBottom: "1px solid var(--lineSoft)",
});

const FONT_SAMPLES: { name: string; token: string }[] = [
	{ name: "monoDisplay", token: "{fonts.monoDisplay}" },
	{ name: "monoBody", token: "{fonts.monoBody}" },
	{ name: "ui", token: "{fonts.ui}" },
	{ name: "sans", token: "{fonts.sans}" },
	{ name: "serif", token: "{fonts.serif}" },
	{ name: "mono", token: "{fonts.mono}" },
];

const DURATIONS: { name: string; value: string }[] = [
	{ name: "fast", value: "120ms" },
	{ name: "base", value: "180ms" },
	{ name: "slow", value: "300ms" },
];

const durationDemoClass = css({
	width: "2.5rem",
	height: "2.5rem",
	borderRadius: "0.5rem",
	background: "var(--primary)",
	transitionProperty: "transform",
	transitionTimingFunction: "{easings.standard}",
	cursor: "pointer",
	_hover: { transform: "translateX(2rem)" },
});

export function Tokens() {
	return (
		<div className={pageClass}>
			<h1 style={{ fontSize: "1.75rem", fontWeight: 700 }}>Design tokens</h1>
			<p style={{ opacity: 0.7 }}>
				Values are declared once in <code>panda.config.ts</code> (<code>tokens</code> / <code>semanticTokens</code>) and
				aliased to the app's existing bare <code>--name</code> custom properties via <code>globalCss</code>. Toggle
				Storybook's theme to see the dark-mode values.
			</p>

			{COLOR_GROUPS.map((group) => (
				<section key={group.title}>
					<h2 className={sectionTitleClass}>{group.title}</h2>
					<div className={swatchGridClass}>
						{group.names.map((name) => (
							<ColorSwatch key={name} name={name} />
						))}
					</div>
				</section>
			))}

			<h2 className={sectionTitleClass}>Typography</h2>
			{FONT_SAMPLES.map((f) => (
				<div key={f.name} className={typeRowClass} style={{ fontFamily: `var(--font-${CAMEL_TO_KEBAB(f.name)}, inherit)` }}>
					<code style={{ minWidth: "8rem" }}>{f.name}</code>
					<span>The quick brown fox jumps over the lazy dog</span>
				</div>
			))}

			<h2 className={sectionTitleClass}>Transitions</h2>
			<p style={{ opacity: 0.7, marginBottom: "0.75rem" }}>Hover a square — each uses its named duration token with the standard easing.</p>
			<div style={{ display: "flex", gap: "2rem" }}>
				{DURATIONS.map((d) => (
					<div key={d.name}>
						<div className={durationDemoClass} style={{ transitionDuration: d.value }} />
						<div style={{ marginTop: "0.5rem", fontSize: "0.75rem", opacity: 0.7 }}>
							{d.name} ({d.value})
						</div>
					</div>
				))}
			</div>
		</div>
	);
}

