84	function TerminalDemo() {
85	  const bodyRef = useRef<HTMLDivElement>(null);
86	  // null → reduced motion / no IO support: render the full transcript statically
87	  const [progress, setProgress] = useState<{ line: number; chars: number } | null>(() => {
88	    if (typeof window === "undefined") return null;
89	    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return null;
90	    if (!("IntersectionObserver" in window)) return null;
