96	    const el = bodyRef.current;
97	    if (!el) return;
98	    const io = new IntersectionObserver(
99	      (entries) => {
100	        if (entries.some((e) => e.isIntersecting)) {
101	          io.disconnect();
102	          setTimeout(() => setProgress({ line: 0, chars: 0 }), 500);
103	        }
104	      },
105	      { threshold: 0.35 },
106	    );
107	    io.observe(el);
108	    return () => io.disconnect();
109	  }, [progress]);
