112	    if (progress === null || progress.line < 0 || progress.line >= TERM_LINES.length) return;
113	    const { cls, text } = TERM_LINES[progress.line];
114	    const { perChar, pause } = lineSpeed(cls);
115	    const timer = setTimeout(
116	      () => {
117	        setProgress(
118	          progress.chars < text.length
119	            ? { line: progress.line, chars: progress.chars + 1 }
120	            : { line: progress.line + 1, chars: 0 },
121	        );
122	      },
